PRESETS_BY_ID = {item["id"]: item for item in STYLE_PRESETS}

def list_style_presets():
    return [{key: item[key] for key in ("id", "category", "name", "tagline")} | {"thumbnail": "/arcreel-style-thumbnails/" + item["id"] + ".webp"} for item in STYLE_PRESETS]

def get_style_preset(preset_id):
    return PRESETS_BY_ID.get(preset_id)

def apply_style_preset(prompt, preset_id):
    preset = get_style_preset(preset_id)
    if not preset:
        raise ValueError("未知视频风格预设")
    style = preset["prompt"]
    return prompt if style.lower() in prompt.lower() else "{}\n\nStyle: {}".format(prompt.strip(), style)
